#!/usr/bin/env python3
"""Generate ordered tier suites from Etendo's official JUnit suites (src-test comes from expandCore).

  regression-db.txt       <- org.openbravo.test.StandaloneTestSuite (DB only, no Tomcat)
  integration-server.txt  <- org.openbravo.test.WebserviceTestSuite (needs a running Tomcat)

Each line is a *unit* in the suite's execution order: a test class, or a nested suite kept whole
(nested suites can be order-dependent, e.g. TestCosting). Classes picked by @SelectPackages are
appended after the explicit ones, honoring @ExcludeClassNamePatterns. <tier>.units.json maps every
unit to its leaf classes so shards can be balanced on per-class timings.
Usage: build-suites.py OUT_DIR
"""
import glob, json, os, re, sys

ROOTS = ["src-test/src"] + glob.glob("modules_core/*/src-test") + glob.glob("modules/*/src-test")
SUITE_ANN = r"@(?:Suite\.)?(?:SuiteClasses|SelectClasses)\s*\(\s*\{?(.*?)\}?\s*\)"

def source(fq):
    for r in ROOTS:
        p = os.path.join(r, *fq.split(".")) + ".java"
        if os.path.exists(p):
            body = open(p, encoding="utf-8", errors="ignore").read()
            return re.sub(r"/\*.*?\*/|//[^\n]*", "", body, flags=re.S)  # drop commented-out entries
    return ""

def strings(ann, body):
    m = re.search(rf"@{ann}\s*\(\s*\{{?(.*?)\}}?\s*\)", body, re.S)
    return re.findall(r'"([^"]+)"', m.group(1)) if m else []

def parse(fq):
    """(ordered explicit members, selected packages, exclude patterns) of a suite; ([], [], []) if not a suite."""
    body = source(fq)
    block = re.search(SUITE_ANN, body, re.S)
    pkg = fq.rsplit(".", 1)[0]
    imports = {i.split(".")[-1]: i for i in re.findall(r"^import\s+([\w.]+);", body, re.M)}
    members = [r if "." in r else imports.get(r, f"{pkg}.{r}")
               for r in re.findall(r"([\w.]+)\.class", block.group(1))] if block else []
    return members, strings("SelectPackages", body), strings("ExcludeClassNamePatterns", body)

def package_classes(pkg):
    """Concrete test classes under a package (JUnit selects packages recursively)."""
    out = []
    for r in ROOTS:
        for d, _, files in os.walk(os.path.join(r, *pkg.split("."))):
            for f in sorted(files):
                if f.endswith(".java"):
                    txt = open(os.path.join(d, f), encoding="utf-8", errors="ignore").read()
                    if re.search(r"@(Test|ParameterizedTest)\b", txt) and not re.search(r"abstract\s+class", txt):
                        out.append(os.path.relpath(os.path.join(d, f[:-5]), r).replace(os.sep, "."))
    return out

def leaves(fq, seen=()):
    members, pkgs, _ = parse(fq)
    if not members and not pkgs:
        return [fq]
    out = []
    for m in members + [c for p in pkgs for c in package_classes(p)]:
        if m not in seen:
            out += leaves(m, seen + (fq,))
    return out

def units(suite):
    members, pkgs, excludes = parse(suite)
    ordered = members + [c for p in pkgs for c in package_classes(p) if c not in members]
    excluded = lambda c: any(re.fullmatch(p, c) for p in excludes)
    seen, out = set(), []
    for u in ordered:
        if u not in seen and not excluded(u):
            seen.add(u)
            out.append(u)
    return out

TIERS = {"regression-db": ("org.openbravo.test.StandaloneTestSuite", "DB-only tests (no Tomcat)"),
         "integration-server": ("org.openbravo.test.WebserviceTestSuite", "Tests that need a running Tomcat")}
out_dir = sys.argv[1]
os.makedirs(out_dir, exist_ok=True)
for tier, (suite, desc) in TIERS.items():
    us = units(suite)
    with open(os.path.join(out_dir, f"{tier}.txt"), "w") as f:
        f.write(f"# GENERATED by build-suites.py from {suite} — {desc}. Order matters.\n" + "\n".join(us) + "\n")
    json.dump({u: leaves(u) for u in us}, open(os.path.join(out_dir, f"{tier}.units.json"), "w"), indent=1)
    print(f"{tier}: {len(us)} units from {suite}")
